mapper.select:
select gap_id, order_id, order_no, amount, reason, detail, handled, handle_remark, create_time, handle_time
from hys_payout_gap

    and handled = #{handled}
    and reason = #{reason}
    and order_no like concat('%', #{orderNo}, '%')

order by gap_id desc

mapper.update:
update hys_payout_gap
set handled = #{handled}, handle_remark = #{handleRemark}, handle_time = now()
where gap_id = #{gapId}
